function symbol(name,pose,helmet=false){
 if(name==='child')return child('#d87684',pose,false,helmet);if(name==='brother')return child('#7aaa91',pose);if(name==='sister')return child('#b490c4',pose,false,helmet);
 if(name==='Mum')return child('#b381ae',pose,true);if(name==='Dad')return child('#568bad',pose,true);if(name==='guest')return child('#a59b64',pose,true);if(name==='Grandma')return child('#8299b7',pose,true).replaceAll('#574338','#aaa39b');
 if(name==='ball')return '<circle cx="50" cy="50" r="47" fill="#e0bb65" stroke="#916f40" stroke-width="3"/><path d="M4 50h92M50 4q-37 47 0 92M50 4q37 47 0 92" fill="none" stroke="#fff2c7" stroke-width="6"/>';
 return extra[name]||sceneSymbol(name);
}
export function valueObject(word){
 const key=word.toLowerCase(),num={one:1,two:2,three:3,four:4};let art='';
 if(num[key])art=Array.from({length:num[key]},(_,i)=>'<g data-object="date" transform="translate('+(i*90)+' 0)">'+extra.date+'</g>').join('');
 else art=symbol(({dad:'Dad',mum:'Mum',brother:'brother',bird:'bird',date:'date',dates:'dates',shoe:'shoe',toys:'toys',drawing:'flower-drawing',flower:'flower',paper:'paper',foot:'foot',hand:'hand',shoes:'shoes',bun:'bun',cloth:'cloth',pencil:'pencil',floor:'floor',tree:'tree',sky:'sky',bus:'bus',hat:'hat',cup:'red-cup',sun:'sun',cat:'cat',pig:'pig',hen:'hen',truck:'truck',bike:'bike',ball:'ball',gate:'gate',bed:'bed',table:'table',tower:'tower',blocks:'blocks',box:'box',arm:'arm',crumb:'crumb',ant:'ant',twig:'twig',plate:'plate',apple:'apple'})[key]||word,'stand');
 return finishIllustration('<svg class="value-object" viewBox="0 0 '+(num[key]?num[key]*90+10:100)+' 100" role="img" aria-label="'+esc(word)+'">'+art+'</svg>');
}
export function valueScene(story,line){
 const scene=configs[story.id.slice(7)]?.[story.sceneLines[line]];if(!scene)throw Error('Missing values scene '+story.id+' '+line);
 let background='<rect width="600" height="310" rx="20" fill="'+(scene.background==='room'?'#f7efdf':'#e5f0f4')+'"/><path d="M0 226h600v84H0Z" fill="'+(scene.background==='room'?'#e5d6c1':'#d6e0c4')+'"/>';
 if(scene.background==='path')background+='<path d="M155 310 260 115h80l105 195Z" fill="#d4bda1"/>';
 if(scene.background==='enclosed')background+='<path d="M0 160h600M0 187h600m-570-40v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66m40-66v66" stroke="#c6ad89" stroke-width="6"/>';
 const art=scene.objects.map(({name,x,y,w,h,pose})=>'<g data-object="'+name+'" data-pose="'+pose+'" transform="translate('+(x-w/2)+' '+(y-h)+') scale('+w/100+' '+h/100+')">'+symbol(name,pose,story.id==='values-turns-bike'&&['child','sister'].includes(name))+'</g>').join('');
 const shadows=scene.objects.filter(o=>['child','brother','sister','Mum','Dad','guest','Grandma','cat'].includes(o.name)).map(o=>groundShadow(o.x,o.y+1,o.w)).join('');
 return finishIllustration('<svg class="sentence-scene value-scene" viewBox="0 0 600 310" role="img" aria-label="'+esc(story.sentences[line])+'"><title>'+esc(story.sentences[line])+'</title>'+background+shadows+scene.extras+art+'</svg>');
}
